// File: src/components/ReferralHistoryTable.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || "http://localhost:8080/api";

export default function ReferralHistoryTable() {
  const [referrals, setReferrals] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchReferralHistory();
  }, []);

  const fetchReferralHistory = async () => {
    try {
      const token = localStorage.getItem("authToken");
      const res = await axios.get(`${API_BASE_URL}/bonus/history?gameId=my`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      const referralData = res.data.filter(item => item.type === "Referral");
      referralData.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
      setReferrals(referralData);
    } catch (err) {
      console.error("Error fetching referral history:", err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <p className="text-center p-4">Loading referral history...</p>;
  if (referrals.length === 0) return <p className="text-center p-4">No referral bonuses yet.</p>;

  return (
    <div className="max-w-5xl mx-auto p-4">
      <h2 className="text-2xl font-bold mb-4 text-center text-gray-800">Referral Bonus History</h2>
      <div className="overflow-x-auto shadow-md rounded-lg border border-gray-200">
        <table className="min-w-full bg-white">
          <thead className="bg-gray-100">
            <tr>
              <th className="text-left py-2 px-4 font-medium text-gray-700">#</th>
              <th className="text-left py-2 px-4 font-medium text-gray-700">Game ID / Referrer</th>
              <th className="text-left py-2 px-4 font-medium text-gray-700">Bonus Amount</th>
              <th className="text-left py-2 px-4 font-medium text-gray-700">Date</th>
            </tr>
          </thead>
          <tbody>
            {referrals.map((item, index) => (
              <tr
                key={index}
                className={index % 2 === 0 ? "bg-white" : "bg-gray-50"}
              >
                <td className="py-2 px-4">{index + 1}</td>
                <td className="py-2 px-4">{item.sourceGameId || "N/A"}</td>
                <td className="py-2 px-4 text-green-600 font-semibold">
                  {item.amount}
                </td>
                <td className="py-2 px-4">{new Date(item.createdAt).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
